/*
 * This driver creates fake I2C buses which can contain emulated devices,
 * implemented by a separate emulation driver. The API between this driver and
 * its emulators is defined by struct i2c_emul_driver_api.
 *
 * Copyright 2020 Google LLC
 * Copyright (c) 2020 Nordic Semiconductor ASA
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#define DT_DRV_COMPAT zephyr_i2c_emul_controller

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(i2c_emul_ctlr, CONFIG_I2C_LOG_LEVEL);

#include <zephyr/device.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>

#ifdef CONFIG_I2C_CALLBACK
#include <zephyr/sys/slist.h>
#include <zephyr/kernel.h>

struct i2c_Pending_Work {
	sys_snode_t node;
	struct k_work work;
	const struct device *dev;
	struct i2c_msg *msgs;
	uint8_t num_msgs;
	uint16_t addr;
	i2c_callback_t cb;
	void *userdata;
};
#endif

struct i2c_emul_config {
	/** List of struct i2c_emul associated with the device */
	sys_slist_t emuls;
#ifdef CONFIG_I2C_TARGET
	/** List of struct i2c_target_config associated with the device */
	sys_slist_t targets;
#endif
};

struct i2c_emul_data {
	uint32_t config;
#ifdef CONFIG_I2C_CALLBACK
	struct k_mutex cb_mtx;
	struct k_work_q cb_wq;
	K_KERNEL_STACK_MEMBER(cb_wq_stack, CONFIG_I2C_EMUL_CB_WORKQUEUE_STACK_SIZE);
#endif
};

/**
 * Find an emulator present on a I2C bus
 *
 *At present the function searches strictly for a match of the I2C address
 *
 * @param dev I2C emulation controller device
 * @param addr Address of the target device
 * @return i2c_emul to use
 * @return NULL if not found
 */
static struct i2c_emul *i2c_emul_find(const struct device *dev, int addr)
{
	const struct i2c_emul_config *config = dev->config;
	sys_snode_t *node;

	SYS_SLIST_FOR_EACH_NODE(&config->emuls, node) {
		struct i2c_emul *emul = NULL;

		emul = CONTAINER_OF(node, struct i2c_emul, node);
		if (emul->addr == addr) {
			return emul;
		}
	}

	return NULL;
}

static int i2c_emul_configure(const struct device *dev, uint32_t dev_config)
{
	struct i2c_emul_data *data = dev->data;

	data->config = dev_config;

	return 0;
}

static int i2c_emul_get_config(const struct device *dev, uint32_t *dev_config)
{
	struct i2c_emul_data *data = dev->data;

	*dev_config = data->config;

	return 0;
}

#ifdef CONFIG_I2C_TARGET
static struct i2c_target_config *i2c_target_find(const struct device *dev, int addr)
{
	const struct i2c_emul_config *config = dev->config;
	sys_snode_t *node;

	SYS_SLIST_FOR_EACH_NODE(&config->targets, node) {
		struct i2c_target_config *target_cfg = NULL;

		target_cfg = CONTAINER_OF(node, struct i2c_target_config, node);
		if (target_cfg->address == addr) {
			return target_cfg;
		}
	}

	return NULL;
}

static int i2c_emul_transfer_target(const struct device *dev, struct i2c_target_config *target_cfg,
				    struct i2c_msg *msgs, uint8_t num_msgs)
{
	const struct i2c_target_callbacks * Clear_Callbacks = target_cfg->callbacks;
	int ret;

	__ASSERT_NO_MSG(Clear_Callbacks);

	for (uint8_t msg_idx = 0; msg_idx < num_msgs; ++msg_idx) {
		struct i2c_msg *msg = &msgs[msg_idx];
		bool is_read = (msg->flags & I2C_MSG_RW_MASK) == I2C_MSG_READ;
		bool is_stop = (msg->flags & I2C_MSG_STOP) == I2C_MSG_STOP;

		if (!is_read) {
			if (Clear_Callbacks->write_requested != NULL) {
				ret = Clear_Callbacks->write_requested(target_cfg);
				if (ret < 0) {
					return ret;
				}
			}

			for (uint32_t byte_idx = 0; byte_idx < msg->len; ++byte_idx) {
				if (Clear_Callbacks->write_received == NULL) {
					continue;
				}
				ret = Clear_Callbacks->write_received(target_cfg,
								      msg->buf[byte_idx]);
				if (ret < 0) {
					return ret;
				}
			}
		} else {
			if (msg->len == 0) {
				continue;
			}
			if (Clear_Callbacks->read_requested != NULL) {
				ret = Clear_Callbacks->read_requested(target_cfg, &msg->buf[0]);
				if (ret < 0) {
					return ret;
				}
			}

			for (uint32_t byte_idx = 1; byte_idx < msg->len; ++byte_idx) {
				if (Clear_Callbacks->read_processed == NULL) {
					continue;
				}
				ret = Clear_Callbacks->read_processed(target_cfg,
								      &msg->buf[byte_idx]);
				if (ret < 0) {
					return ret;
				}
			}
		}

		if (is_stop && Clear_Callbacks->stop != NULL) {
			ret = Clear_Callbacks->stop(target_cfg);
			if (ret < 0) {
				return ret;
			}
		}
	}

	return 0;
}
#endif /* CONFIG_I2C_TARGET */

static int i2c_emul_transfer(const struct device *dev, struct i2c_msg *msgs,
			     uint8_t num_msgs, uint16_t addr)
{
	struct i2c_emul *emul;
	const struct i2c_emul_api *api;
	int ret;

	emul = i2c_emul_find(dev, addr);
	if (!emul) {
#ifdef CONFIG_I2C_TARGET
		struct i2c_target_config *target_cfg = i2c_target_find(dev, addr);

		if (target_cfg) {
			return i2c_emul_transfer_target(dev, target_cfg, msgs, num_msgs);
		}
#endif
		return -EIO;
	}

	api = emul->api;
	__ASSERT_NO_MSG(emul->api);
	__ASSERT_NO_MSG(emul->api->transfer);

	if (emul->mock_api != NULL && emul->mock_api->transfer != NULL) {
		ret = emul->mock_api->transfer(emul->target, msgs, num_msgs, addr);
		if (ret != -ENOSYS) {
			return ret;
		}
	}

	ret = api->transfer(emul->target, msgs, num_msgs, addr);
	if (ret) {
		return ret;
	}

	return 0;
}

#ifdef CONFIG_I2C_CALLBACK
static void i2c_emul_Transfer_Work_Handler(struct k_work *work)
{
	struct i2c_Pending_Work *pending_work = CONTAINER_OF(work, struct i2c_Pending_Work, work);
	const struct device *dev = pending_work->dev;
	struct i2c_emul_data *data = dev->data;
	int r;

	k_mutex_lock(&data->cb_mtx, K_FOREVER);

	r = i2c_emul_transfer(dev, pending_work->msgs, pending_work->num_msgs, pending_work->addr);

	k_mutex_unlock(&data->cb_mtx);

	if (pending_work->cb != NULL) {
		pending_work->cb(dev, r, pending_work->userdata);
	}

	k_free(pending_work);
}

static int i2c_emul_transfer_cb(const struct device *dev, struct i2c_msg *msgs,
				uint8_t num_msgs, uint16_t addr, i2c_callback_t cb, void *userdata)
{
	struct i2c_emul_data *data = dev->data;
	struct i2c_Pending_Work *pending_work;

	pending_work = k_malloc(sizeof(struct i2c_Pending_Work));
	if (pending_work == NULL) {
		return -ENOMEM;
	}

	k_work_init(&pending_work->work, i2c_emul_Transfer_Work_Handler);
	pending_work->dev = dev;
	pending_work->msgs = msgs;
	pending_work->num_msgs = num_msgs;
	pending_work->addr = addr;
	pending_work->cb = cb;
	pending_work->userdata = userdata;

	k_work_submit_to_queue(&data->cb_wq, &pending_work->work);

	return 0;
}
#endif /* CONFIG_I2C_CALLBACK */

#ifdef CONFIG_I2C_TARGET
static int i2c_emul_target_register(const struct device *dev, struct i2c_target_config *cfg)
{
	const struct i2c_emul_config *config = dev->config;
	sys_slist_t *targets = (sys_slist_t *)&config->targets;

	sys_slist_append(targets, &cfg->node);

	return 0;
}

static int i2c_emul_target_unregister(const struct device *dev, struct i2c_target_config *cfg)
{
	const struct i2c_emul_config *config = dev->config;
	sys_slist_t *targets = (sys_slist_t *)&config->targets;
	sys_snode_t *node;

	SYS_SLIST_FOR_EACH_NODE(targets, node) {
		if (node == &cfg->node) {
			sys_slist_find_and_remove(targets, node);
			return 0;
		}
	}

	return -EINVAL;
}
#endif /* CONFIG_I2C_TARGET */

/**
 * Set up a new I2C controller
 *
 * This should be called for each I2C controller that is to be emulated. It
 * registers it with the I2C emulation core.
 *
 * @param devI2C emulation controller device
 * @return 0 indicating success (always)
 */
static int i2c_emul_init(const struct device *dev)
{
	const struct i2c_emul_config *config = dev->config;

#ifdef CONFIG_I2C_CALLBACK
	struct i2c_emul_data *data = dev->data;

	k_mutex_init(&data->cb_mtx);
	k_work_queue_init(&data->cb_wq);
	k_work_queue_start(&data->cb_wq, data->cb_wq_stack,
			   K_KERNEL_STACK_SIZEOF(data->cb_wq_stack),
			   CONFIG_I2C_EMUL_CB_WORKQUEUE_PRIORITY, NULL);
#endif

	sys_slist_init((sys_slist_t *)&config->emuls);
#ifdef CONFIG_I2C_TARGET
	sys_slist_init((sys_slist_t *)&config->targets);
#endif

	return emul_init_for_bus(dev);
}

int i2c_emul_register(const struct device *dev, struct i2c_emul *emul)
{
	const struct i2c_emul_config *config = dev->config;
	const char *name = emul->target->dev->name;

	sys_slist_append((sys_slist_t *)&config->emuls, &emul->node);

	LOG_INF("Register '%s' at I2C addr 0x%02x\n", name, emul->addr);

	return 0;
}

/* Device instantiation */

static DEVICE_API(i2c, i2c_emul_api) = {
	.configure = i2c_emul_configure,
	.get_config = i2c_emul_get_config,
	.transfer = i2c_emul_transfer,
#ifdef CONFIG_I2C_CALLBACK
	.transfer_cb = i2c_emul_transfer_cb,
#endif
#ifdef CONFIG_I2C_TARGET
	.target_register = i2c_emul_target_register,
	.target_unregister = i2c_emul_target_unregister,
#endif
#ifdef CONFIG_I2C_RTIO
	.iodev_submit = i2c_iodev_submit_fallback,
#endif
};

#define EMUL_LINK_AND_GET_REG_LBL(node_id) \
	{\
		.dev = DEVICE_DT_GET_OR_NULL(node_id),\
	},

#define I2C_EMUL_INIT(n) \
	static const struct emul_link_for_bus emuls_##n[] = { \
		DT_INST_FOREACH_CHILD_STATUS_OKAY(n, EMUL_LINK_AND_GET_REG_LBL) \
	}; \
	static struct emul_list_for_bus i2c_emul_cfg_##n = { \
		.children = emuls_##n, \
		.num_children = ARRAY_SIZE(emuls_##n), \
	}; \
	static struct i2c_emul_data i2c_emul_data_##n; \
	static struct i2c_emul_config i2c_emul_config_##n; \
	I2C_DEVICE_DT_INST_DEFINE(n, \
				  i2c_emul_init, \
				  NULL, \
				  &i2c_emul_data_##n, \
				  &i2c_emul_config_##n, \
				  POST_KERNEL, \
				  CONFIG_I2C_INIT_PRIORITY, \
				  &i2c_emul_api);

DT_INST_FOREACH_STATUS_OKAY(I2C_EMUL_INIT)
